from pydantic import BaseModel

class KitapOlustur(BaseModel):
    baslik: str
    yazar: str
    sayfa_sayisi: int

class KitapYanit(KitapOlustur):
    id: int
    odunc_alindi_mi: bool

    class Config:
        from_attributes = True

from typing import List

@app.get('/kitaplar', response_model=List[KitapYanit])
def kitaplari_listele(db: Session = Depends(get_db)):
    # SELECT * FROM kitaplar
    return db.query(KitapModel).all()

@app.get('/kitaplar/{kitap_id}', response_model=KitapYanit)
def tek_kitap_getir(kitap_id: int, db: Session = Depends(get_db)):
    kitap = db.query(KitapModel).filter(KitapModel.id == kitap_id).first()
    if not kitap:
        raise HTTPException(status_code=404, detail='Kitap bulunamadı!')
    return kitap

@app.put('/kitaplar/{kitap_id}/odunc-al', response_model=KitapYanit)
def odunc_al(kitap_id: int, db: Session = Depends(get_db)):
    kitap = db.query(KitapModel).filter(KitapModel.id == kitap_id).first()
    if not kitap:
        raise HTTPException(status_code=404, detail='Kitap bulunamadı!')

    kitap.odunc_alindi_mi = True
    db.commit()
    db.refresh(kitap)
    return kitap

@app.delete('/kitaplar/{kitap_id}')
def kitap_sil(kitap_id: int, db: Session = Depends(get_db)):
    kitap = db.query(KitapModel).filter(KitapModel.id == kitap_id).first()
    if not kitap:
        raise HTTPException(status_code=404, detail='Kitap bulunamadı!')

    db.delete(kitap)
    db.commit()
    return {'mesaj': f'"{kitap.baslik}" başarıyla silindi.'}

@app.get('/kitaplar/sayfala')
def sayfali_getir(skip: int = 0, limit: int = 10, db: Session = Depends(get_db)):
    return db.query(KitapModel).offset(skip).limit(limit).all()

@app.put('/kitaplar/{kitap_id}/iade-et', response_model=KitapYanit)
def iade_et(kitap_id: int, db: Session = Depends(get_db)):
    kitap = db.query(KitapModel).filter(KitapModel.id == kitap_id).first()
    if not kitap:
        raise HTTPException(status_code=404, detail='Kitap yok!')
    kitap.odunc_alindi_mi = False
    db.commit()
    db.refresh(kitap)
    return kitap
